G1=$(group 'fwshift-external' 'FWShift: for the interfaces of 0.0.0.0-10.9.255.255 10.11.0.0-172.16.29.255 172.16.31.0-192.168.9.255 192.168.11.0-192.168.19.255 192.168.21.0-198.51.99.255 198.51.101.0-255.255.255.255') || exit 1
