G3=$(group 'fwshift-dmz' 'FWShift: for the interfaces of 172.16.30.0-172.16.30.9 172.16.30.11-172.16.30.255') || exit 1
# attach fwshift-dmz-2: 172.16.30.10
G4=$(group 'fwshift-dmz-2' 'FWShift: for the interfaces of 172.16.30.10') || exit 1
# attach fwshift-internal-2: 192.168.10.0 192.168.10.2-192.168.10.4 192.168.10.6-192.168.10.19 192.168.10.30-192.168.10.39 192.168.10.41-192.168.10.59 192.168.10.61-192.168.10.255
G5=$(group 'fwshift-internal-2' 'FWShift: for the interfaces of 192.168.10.0 192.168.10.2-192.168.10.4 192.168.10.6-192.168.10.19 192.168.10.30-192.168.10.39 192.168.10.41-192.168.10.59 192.168.10.61-192.168.10.255') || exit 1
