# attach fwshift-external-3: 198.51.100.7
G12=$(group 'fwshift-external-3' 'FWShift: for the interfaces of 198.51.100.7') || exit 1
# attach fwshift-vendor_vpn: 198.51.100.64/27
G13=$(group 'fwshift-vendor_vpn' 'FWShift: for the interfaces of 198.51.100.64/27') || exit 1
